test('every supported board can be completed and matched cards stay named', async ({ page }) => {
  test.setTimeout(120_000);
  await expect(card(page, 0, 4)).toHaveAttribute('aria-label', /closed/, { timeout: 1500 });

  const pending = JSON.stringify({ version: 1, boardCode: 'np1-4-1', matched: [0, 11], selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 }, moves: 2, elapsedMs: 1500, started: true });
  await page.getByLabel('Snapshot JSON').fill(pending);
  await page.getByRole('button', { name: 'Load snapshot' }).click();
  await expect(page.getByText('Loaded snapshot. Select Resume to continue.')).toBeVisible();
  await expect(card(page, 3, 4)).toHaveAttribute('aria-disabled', 'true');
  await card(page, 3, 4).click();
  await expect(page.getByText('Moves: 2')).toBeVisible();
  await page.getByRole('button', { name: 'Resume' }).click();
  await expect(page.getByRole('button', { name: 'Resume' })).toHaveCount(0);
  await expect(card(page, 0, 4)).toBeFocused();
  await expect(card(page, 1, 4)).toHaveAttribute('aria-label', /closed/, { timeout: 1000 });

  const completed = JSON.stringify({ version: 1, boardCode: 'np1-4-1', matched: Array.from({ length: 16 }, (_, index) => index), selection: { kind: 'closed' }, moves: 8, elapsedMs: 9000, started: true });
  await page.getByLabel('Snapshot JSON').fill(completed);
  await page.getByRole('button', { name: 'Load snapshot' }).click();
  await expect(page.getByText('Loaded completed snapshot.')).toBeVisible();
  await expect(page.getByText('Best: 9')).toBeVisible();
  await expect(page.locator('.win-banner')).not.toHaveClass(/win-celebrate/);

  await page.getByLabel('Board code').fill('np1-4-01');
  await page.getByRole('button', { name: 'Load board' }).click();
  await expect(page.getByText('Invalid board code.')).toBeVisible();
  await expect(page.getByText('Pairs: 8/8')).toBeVisible();
  await page.getByLabel('Snapshot JSON').fill('{broken');
  await page.getByRole('button', { name: 'Load snapshot' }).click();
  await expect(page.getByText('Invalid snapshot.')).toBeVisible();
});

test('saved size survives reload and bad preference data is ignored', async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem('neon-pairs.last-size.v1', '"not-a-size"'));
  await page.goto(BASE);
  await expect(page.getByLabel('Grid size')).toHaveValue('4');
  await page.getByLabel('Grid size').selectOption('6');
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await expect(page.getByText('Pairs: 0/18')).toBeVisible();
});

test('the built HTML opens from disk without HTTP requests', async ({ page }) => {

import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react';
import type { KeyboardEvent } from 'react';
import type { GameState } from '../types.ts';
import { FaceArtwork, faceName, BackArtwork } from './Face.tsx';
import './Board.css';

export type BoardHandle = Readonly<{ focusRemembered: () => void }>;
type Props = Readonly<{ game: GameState; paused: boolean; resetKey: number; onActivate: (index: number) => void }>;

export const Board = forwardRef<BoardHandle, Props>(function Board({ game, paused, resetKey, onActivate }, ref) {
  const [remembered, setRemembered] = useState(0);
  const [cardSize, setCardSize] = useState(44);
  const areaRef = useRef<HTMLDivElement>(null);
  const buttonsRef = useRef(new Map<number, HTMLButtonElement>());
  useImperativeHandle(ref, () => ({ focusRemembered: () => buttonsRef.current.get(remembered)?.focus() }), [remembered]);

  useEffect(() => { setRemembered(0); }, [resetKey]);
  useEffect(() => {
    const area = areaRef.current;
    if (!area) return;
    const measure = () => {
      const available = area.clientWidth - 12 - 6 * (game.board.size - 1);
      setCardSize(Math.max(44, Math.min(88, Math.floor(available / game.board.size))));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(area);
    return () => observer.disconnect();
  }, [game.board.size]);

  const moveFocus = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const size = game.board.size;
    const row = Math.floor(index / size);
    const column = index % size;
    let destination = index;
    if (event.key === 'ArrowLeft' && column > 0) destination -= 1;
    else if (event.key === 'ArrowRight' && column < size - 1) destination += 1;
    else if (event.key === 'ArrowUp' && row > 0) destination -= size;
    else if (event.key === 'ArrowDown' && row < size - 1) destination += size;
    else return;
    event.preventDefault();
    buttonsRef.current.get(destination)?.focus();
  };

  return <div className="board-scroll" ref={areaRef}>
    <div className="board-grid" role="group" aria-label={`${game.board.size} by ${game.board.size} card board`} style={{ '--board-size': game.board.size, '--card-size': `${cardSize}px` } as React.CSSProperties}>
      {game.board.deck.map((faceId, index) => {
        const matched = game.matched.includes(index);
        const selected = game.selection.kind === 'one' && game.selection.index === index;
        const mismatch = game.selection.kind === 'mismatch' && (game.selection.first === index || game.selection.second === index);
        const revealed = matched || selected || mismatch;
        const row = Math.floor(index / game.board.size) + 1;
        const column = index % game.board.size + 1;
        const stateName = matched ? 'matched' : 'revealed';
        const name = revealed ? `Row ${row}, column ${column}, ${faceName(faceId)}, ${stateName}` : `Row ${row}, column ${column}, closed`;
        return <button
          key={index}
          ref={(element) => { if (element) buttonsRef.current.set(index, element); else buttonsRef.current.delete(index); }}
          className={`card${revealed ? ' card-revealed' : ''}${matched ? ' card-matched' : ''}`}
          type="button"
          aria-label={name}
          aria-disabled={matched || paused ? 'true' : undefined}
          tabIndex={remembered === index ? 0 : -1}
          onFocus={(event) => {
            setRemembered(index);
            event.currentTarget.scrollIntoView({ block: 'nearest', inline: 'nearest' });
          }}
          onKeyDown={(event) => moveFocus(event, index)}
          onClick={() => onActivate(index)}
        >
          {revealed ? <FaceArtwork id={faceId} /> : <BackArtwork />}
          {matched && <span aria-hidden="true" className="matched-check">✓</span>}
        </button>;
      })}
    </div>
  </div>;
});

  const [controlStatus, setControlStatus] = useState('');
  const [announcement, setAnnouncement] = useState('');
  const [celebration, setCelebration] = useState(0);
  const [epoch, setEpoch] = useState(0);
  const gameRef = useRef(game);
  const pausedRef = useRef(false);
  const epochRef = useRef(0);
  const lastTimeRef = useRef<number | null>(null);
  const fractionalMsRef = useRef(0);
  const preparedStartRef = useRef(false);
  const announcementTimerRef = useRef<number | null>(null);
  const announcementQueueRef = useRef<string[]>([]);
  const announcementBusyRef = useRef(false);
  const tickRef = useRef<(force: boolean) => void>(() => undefined);

  const commit = useCallback((next: GameState) => { gameRef.current = next; setGame(next); }, []);
  const replace = (next: GameState, pause: boolean) => {
    epochRef.current += 1;
    lastTimeRef.current = null;
    fractionalMsRef.current = 0;
    preparedStartRef.current = false;
    gameRef.current = next;
    setGame(next);
    pausedRef.current = pause;
    setPaused(pause);
    setEpoch(epochRef.current);
    setBoardDraft(next.board.code);
    setCelebration(0);
  };
  const announce = useCallback((message: string) => {
    announcementQueueRef.current.push(message);
    if (announcementBusyRef.current) return;
    const showNext = () => {
      const next = announcementQueueRef.current.shift();
      if (next === undefined) { announcementBusyRef.current = false; return; }
      announcementBusyRef.current = true;
      setAnnouncement('');
      announcementTimerRef.current = window.setTimeout(() => {
        setAnnouncement(next);
        announcementTimerRef.current = window.setTimeout(() => {
          setAnnouncement('');
          announcementTimerRef.current = window.setTimeout(showNext, 25);
        }, 800);
      }, 25);
    };
    showNext();
  }, [commit]);

  const tick = useCallback((force: boolean) => {
    if (pausedRef.current || (!force && document.hidden)) return;
    const now = performance.now();
    const last = lastTimeRef.current;
    lastTimeRef.current = now;
    if (last === null) return;
    const exact = now - last + fractionalMsRef.current;
    const whole = Math.floor(exact);
    fractionalMsRef.current = exact - whole;
    if (whole > 0) commit(advanceGame(gameRef.current, whole));
  }, [commit]);
  tickRef.current = tick;

  useEffect(() => {
    const won = isWon(game);
    const active = game.started && !won && !paused;
    if (!active) return;
    const callbackEpoch = epoch;
    if (!preparedStartRef.current) lastTimeRef.current = performance.now();
    preparedStartRef.current = false;
    const timer = window.setInterval(() => {
      if (epochRef.current === callbackEpoch) tickRef.current(false);
    }, 50);
    const visibility = () => {
      if (epochRef.current !== callbackEpoch) return;
      if (document.hidden) tickRef.current(true);
      else lastTimeRef.current = performance.now();
    };
    document.addEventListener('visibilitychange', visibility);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [epoch, game.started, game.board.code, paused, isWon(game), tick]);

  useEffect(() => () => {
    if (announcementTimerRef.current !== null) window.clearTimeout(announcementTimerRef.current);
    announcementQueueRef.current = [];
  }, []);

  const activate = useCallback((index: number) => {
    if (pausedRef.current || document.hidden) return;
    tickRef.current(true);
    const before = gameRef.current;
    const next = activateCard(before, index);
    if (next === before) return;
    if (!before.started && next.started) {
      lastTimeRef.current = performance.now();
      fractionalMsRef.current = 0;
      preparedStartRef.current = true;
    }
    commit(next);
    if (next.moves > before.moves) {
      const matched = pairCount(next) > pairCount(before);
      if (matched && isWon(next)) announce(`Pair found. All pairs found in ${next.moves} moves and ${formatTime(next.elapsedMs)}.`);
      else if (matched) announce(`Pair found. ${pairCount(next)} ${pairCount(next) === 1 ? 'pair' : 'pairs'} matched.`);
      else announce('No match. Cards close after a short pause.');
      if (isWon(next) && !isWon(before)) {
        setBestRecords(saveBestIfBetter(next.board.size, next.moves));
        setCelebration((current) => current + 1);
      }
    }
  }, [announce, commit]);

  const startFresh = (nextSize = size) => {
    const next = freshGame(nextSize);
    replace(next, false);
    setSize(nextSize);
  };
  const changeSize = (nextSize: BoardSize) => {
    saveLastSize(nextSize);
    startFresh(nextSize);
  };
  const restart = () => {
    const next = createGame(gameRef.current.board.code);
    if (next) replace(next, false);
  };
  const loadBoard = () => {
    const board = parseBoardCode(boardDraft.trim());
    if (!board) { reportControl('Invalid board code.'); return; }
    const next = createGame(board.code);
    if (!next) { reportControl('Invalid board code.'); return; }
    replace(next, false);
    setSize(board.size);
    saveLastSize(board.size);
  };
  const loadSnapshot = () => {
    const next = decodeSnapshot(snapshotDraft);
    if (!next) { reportControl('Invalid snapshot.'); return; }
    const completed = isWon(next);
    replace(next, !completed);
    setSize(next.board.size);
    saveLastSize(next.board.size);
    reportControl(completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
  };
  const reportControl = (message: string) => {
    setControlStatus(message);
    announce(message);
  };
  const resume = () => { pausedRef.current = false; setPaused(false); };
  const exportSnapshot = () => setSnapshotDraft(encodeSnapshot(gameRef.current));
  const best = bestRecords[size];

  return {
    game, size, paused, best, boardDraft, snapshotDraft, controlStatus, announcement, celebration, epoch,
    setBoardDraft, setSnapshotDraft, activate, startFresh, changeSize, restart, loadBoard, loadSnapshot, resume, exportSnapshot,
  };
}

