import { resolve } from 'node:path';
import { parseBoardCode } from '../src/game/board/deal.ts';

const BASE = 'http://127.0.0.1:4173';

function card(page: import('@playwright/test').Page, index: number, size: number) {
  const row = Math.floor(index / size) + 1;
  const column = index % size + 1;
  return page.getByRole('button', { name: new RegExp(`^Row ${row}, column ${column}, `) });
}

function pairs(deck: readonly number[]) {
  const positions = new Map<number, number[]>();
  deck.forEach((face, index) => positions.set(face, [...(positions.get(face) ?? []), index]));
  return [...positions.values()];
}

async function loadBoard(page: import('@playwright/test').Page, code: string) {
  await page.getByText('Reproduce a game').click();
  await page.getByLabel('Board code').fill(code);
  await page.getByRole('button', { name: 'Load board' }).click();
}

test('accessible keyboard journey plays a complete 4 by 4 game', async ({ page }) => {
  await page.goto(BASE);
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  await expect(page.getByLabel('Grid size')).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: 'New Game' })).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(page.getByRole('button', { name: 'New Game' })).toBeFocused();
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  await expect(card(page, 0, 4)).toBeFocused();

  const code = await page.getByLabel('Board code').inputValue();
  const deck = parseBoardCode(code)?.deck;
  expect(deck).toHaveLength(16);
  const initialTree = await page.getByRole('group', { name: '4 by 4 card board' }).ariaSnapshot();
  expect(initialTree).toContain('Row 1, column 1, closed');
  expect(initialTree).toContain('Row 4, column 4, closed');

  let focused = 0;
  let revealedTree = '';
  const moveTo = async (destination: number) => {
    while (Math.floor(focused / 4) > Math.floor(destination / 4)) { await page.keyboard.press('ArrowUp'); focused -= 4; }
    while (Math.floor(focused / 4) < Math.floor(destination / 4)) { await page.keyboard.press('ArrowDown'); focused += 4; }
    while (focused % 4 > destination % 4) { await page.keyboard.press('ArrowLeft'); focused -= 1; }
    while (focused % 4 < destination % 4) { await page.keyboard.press('ArrowRight'); focused += 1; }
  };
  const positions = new Map<number, number[]>();
  deck!.forEach((face, index) => positions.set(face, [...(positions.get(face) ?? []), index]));
  for (const pair of positions.values()) {
    await moveTo(pair[0]!);
    await page.keyboard.press('Enter');
    const currentTree = await page.getByRole('group', { name: '4 by 4 card board' }).ariaSnapshot();
    expect(currentTree).toContain('revealed');
    if (!revealedTree) revealedTree = currentTree;
    await moveTo(pair[1]!);
    await page.keyboard.press('Space');
  }

  await expect(page.getByRole('heading', { name: 'Beautifully done.' })).toBeVisible();
  await expect(page.getByText('Pairs: 8/8')).toBeVisible();
  await expect(page.locator('.live-announcer')).toContainText(/Pair found\. All pairs found in 8 moves and \d+:\d{2}\./, { timeout: 12_000 });
  const finalTree = await page.getByRole('group', { name: '4 by 4 card board' }).ariaSnapshot();
  expect(finalTree).toContain('matched');
  await test.info().attach('4x4-accessibility-tree-closed', { body: Buffer.from(initialTree), contentType: 'text/plain' });
  await test.info().attach('4x4-accessibility-tree-revealed', { body: Buffer.from(revealedTree), contentType: 'text/plain' });
  await test.info().attach('4x4-accessibility-tree-matched', { body: Buffer.from(finalTree), contentType: 'text/plain' });
  await page.keyboard.press('Tab');
  await expect(page.getByText('Reproduce a game')).toBeFocused();
  await page.getByRole('button', { name: 'New Game' }).click();
  await expect(page.getByText('Pairs: 0/8')).toBeVisible();
  await expect(page.getByRole('button', { name: 'New Game' })).toBeFocused();
});

test('every supported board can be completed and matched cards stay named', async ({ page }) => {
  test.setTimeout(120_000);
  await page.goto(BASE);
  for (const size of [4, 6, 8, 10, 12, 14, 16]) {
    if (size !== 4) await page.getByLabel('Grid size').selectOption(String(size));
    const code = await page.getByLabel('Board code').inputValue();
    const deck = parseBoardCode(code)?.deck;
    expect(deck).toHaveLength(size * size);
    for (const pair of pairs(deck!)) {
      await card(page, pair[0]!, size).click();
      await card(page, pair[1]!, size).click();
    }
    const total = size * size / 2;
    await expect(page.getByRole('heading', { name: 'Beautifully done.' })).toBeVisible();
    await expect(page.getByText(`Pairs: ${total}/${total}`)).toBeVisible();
    await expect(page.getByText(`Moves: ${total}`)).toBeVisible();
    await expect(card(page, 0, size)).toHaveAttribute('aria-disabled', 'true');
    const matchedTree = await page.getByRole('group', { name: `${size} by ${size} card board` }).ariaSnapshot();
    expect(matchedTree).toContain('matched');
  }
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('16');
  await expect(page.getByText('Best: 128')).toBeVisible();
});

